    var day = this.getDate() || new Date();
    var difference = parseInt(days)*24*60*60*1000;
    var newDay;
    if (sign === 'add') {
        newDay = new Date(day.valueOf() + difference);
    } else if (sign === 'subtract') {
        newDay = new Date(day.valueOf() - difference);
    }
    // skip disabled days
    var opts = this._o;
    var maxIter = 366;
    var found = false;
    while (maxIter--) {
        if (opts.minDate && newDay < opts.minDate) {
            break;
        }
        if (opts.maxDate && newDay > opts.maxDate) {
            break;
        }
        var disabled = false;
        if (opts.disableWeekends && isWeekend(newDay)) {
            disabled = true;
        }
        if (opts.disableDayFn && opts.disableDayFn(newDay)) {
            disabled = true;
        }
        if (!disabled) {
            found = true;
            break;
        }
        // move one more day in the same direction
        if (sign === 'add') {
            newDay = new Date(newDay.valueOf() + 24*60*60*1000);
        } else {
            newDay = new Date(newDay.valueOf() - 24*60*60*1000);
        }
    }
    if (!found) {
        newDay = day;
    }
    this.setDate(newDay);
},

